/**
 * A JSON parser with CPython `json.loads` semantics.
 *
 * Differences from `JSON.parse` that matter here:
 *   - integers and floats are kept apart (`1` vs `1.0`) and integers stay exact
 *   - `NaN`, `Infinity` and `-Infinity` are accepted
 *   - objects are built with a null prototype, last duplicate key wins
 */

import { mkInt, mkFloat, newObj } from "./pyvalues.mjs";

export class JSONDecodeError extends Error {
  constructor(msg, doc, pos) {
    const lineno = doc.slice(0, pos).split("\n").length;
    const colno = pos - doc.lastIndexOf("\n", pos - 1);
    super(`${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.name = "json.decoder.JSONDecodeError";
  }
}

const WS = new Set([" ", "\t", "\n", "\r"]);

const ESCAPES = {
  '"': '"',
  "\\": "\\",
  "/": "/",
  b: "\b",
  f: "\f",
  n: "\n",
  r: "\r",
  t: "\t",
};

const NUMBER_RE = /^(-?)(0|[1-9]\d*)(\.\d+)?([eE][-+]?\d+)?/;

class Parser {
  constructor(text) {
    this.s = text;
    this.i = 0;
  }

  error(msg, pos = this.i) {
    throw new JSONDecodeError(msg, this.s, pos);
  }

  skipWs() {
    while (this.i < this.s.length && WS.has(this.s[this.i])) this.i += 1;
  }

  parse() {
    this.skipWs();
    const value = this.parseValue();
    this.skipWs();
    if (this.i !== this.s.length) this.error("Extra data");
    return value;
  }

  parseValue() {
    if (this.i >= this.s.length) this.error("Expecting value");
    const c = this.s[this.i];
    if (c === "{") return this.parseObject();
    if (c === "[") return this.parseArray();
    if (c === '"') return this.parseString();
    if (this.s.startsWith("true", this.i)) {
      this.i += 4;
      return true;
    }
    if (this.s.startsWith("false", this.i)) {
      this.i += 5;
      return false;
    }
    if (this.s.startsWith("null", this.i)) {
      this.i += 4;
      return null;
    }
    if (this.s.startsWith("NaN", this.i)) {
      this.i += 3;
      return mkFloat(NaN);
    }
    if (this.s.startsWith("Infinity", this.i)) {
      this.i += 8;
      return mkFloat(Infinity);
    }
    if (this.s.startsWith("-Infinity", this.i)) {
      this.i += 9;
      return mkFloat(-Infinity);
    }
    return this.parseNumber();
  }

  parseNumber() {
    const m = NUMBER_RE.exec(this.s.slice(this.i));
    if (m === null || m[0] === "" || m[0] === "-") this.error("Expecting value");
    const raw = m[0];
    this.i += raw.length;
    if (m[3] === undefined && m[4] === undefined) return mkInt(BigInt(raw));
    return mkFloat(Number(raw));
  }

  parseString() {
    const start = this.i;
    this.i += 1; // opening quote
    let out = "";
    for (;;) {
      if (this.i >= this.s.length) {
        throw new JSONDecodeError("Unterminated string starting at", this.s, start);
      }
      const c = this.s[this.i];
      if (c === '"') {
        this.i += 1;
        return out;
      }
      if (c === "\\") {
        const e = this.s[this.i + 1];
        if (e === undefined) {
          throw new JSONDecodeError("Unterminated string starting at", this.s, start);
        }
        if (e === "u") {
          const hex = this.s.slice(this.i + 2, this.i + 6);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            this.error("Invalid \\uXXXX escape", this.i + 1);
          }
          out += String.fromCharCode(parseInt(hex, 16));
          this.i += 6;
          continue;
        }
        if (!(e in ESCAPES)) {
          this.error(`Invalid \\escape: ${JSON.stringify(e)}`, this.i);
        }
        out += ESCAPES[e];
        this.i += 2;
        continue;
      }
      if (c.charCodeAt(0) < 0x20) {
        this.error("Invalid control character at", this.i);
      }
      out += c;
      this.i += 1;
    }
  }

  parseArray() {
    this.i += 1; // '['
    const arr = [];
    this.skipWs();
    if (this.s[this.i] === "]") {
      this.i += 1;
      return arr;
    }
    for (;;) {
      this.skipWs();
      arr.push(this.parseValue());
      this.skipWs();
      const c = this.s[this.i];
      if (c === ",") {
        this.i += 1;
        continue;
      }
      if (c === "]") {
        this.i += 1;
        return arr;
      }
      this.error("Expecting ',' delimiter");
    }
  }

  parseObject() {
    this.i += 1; // '{'
    const obj = newObj();
    this.skipWs();
    if (this.s[this.i] === "}") {
      this.i += 1;
      return obj;
    }
    for (;;) {
      this.skipWs();
      if (this.s[this.i] !== '"') {
        this.error("Expecting property name enclosed in double quotes");
      }
      const key = this.parseString();
      this.skipWs();
      if (this.s[this.i] !== ":") this.error("Expecting ':' delimiter");
      this.i += 1;
      this.skipWs();
      obj[key] = this.parseValue();
      this.skipWs();
      const c = this.s[this.i];
      if (c === ",") {
        this.i += 1;
        continue;
      }
      if (c === "}") {
        this.i += 1;
        return obj;
      }
      this.error("Expecting ',' delimiter");
    }
  }
}

export function loads(text) {
  return new Parser(text).parse();
}

