 *   (?P<n>...) -> (?<n>...)      named group syntax
 *   (?P=n)     -> \k<n>          named backreference
 *   (?#...)    -> (removed)      inline comment
 *   \A         -> ^              start of string
 *   \Z         -> $              end of string
 *   $          -> (?=\n?$)       Python's `$` also matches before a final \n
 *
 * A pattern JavaScript refuses to compile - or that uses a construct Python
 * itself would reject - is reported as invalid so the caller can raise the
 * same `re.error` the original would.
 */

export class RegexError extends Error {
  constructor(msg) {
    super(msg);
    this.name = "re.error";
  }
}

const cache = new Map();

function translate(pattern) {
  let out = "";
  let inClass = false;
  let i = 0;
  while (i < pattern.length) {
    const c = pattern[i];
    if (c === "\\") {
      const next = pattern[i + 1];
      if (next === undefined) throw new RegexError("bad escape (end of pattern)");
      if (!inClass && next === "A") {
        out += "^";
      } else if (!inClass && next === "Z") {
        out += "$";
      } else if (next === "Z" || next === "A") {
        // inside a character class Python treats these literally-ish; keep raw
        out += "\\" + next;
      } else {
        out += c + next;
      }
      i += 2;
      continue;
    }
    if (inClass) {
      if (c === "]") inClass = false;
      out += c;
      i += 1;
      continue;
    }
    if (c === "[") {
      inClass = true;
      out += c;
      i += 1;
      continue;
    }
    if (c === "$") {
      out += "(?=\\n?$)";
      i += 1;
      continue;
    }
    if (c === "(" && pattern[i + 1] === "?") {
      const rest = pattern.slice(i);
      if (rest.startsWith("(?P<")) {
        out += "(?<";
        i += 4;
        continue;
      }
      if (rest.startsWith("(?P=")) {
        const end = pattern.indexOf(")", i);
        if (end === -1) throw new RegexError("missing ), unterminated name");
        out += "\\k<" + pattern.slice(i + 4, end) + ">";
        i = end + 1;
        continue;
      }
      if (rest.startsWith("(?#")) {
        const end = pattern.indexOf(")", i);
        if (end === -1) throw new RegexError("missing ), unterminated comment");
        i = end + 1;
        continue;
      }
      // `(?<name>` is a JavaScript-only spelling; Python needs `(?P<name>`.
      if (rest.startsWith("(?<") && !"=!".includes(pattern[i + 3])) {
        throw new RegexError("unknown extension ?<");
      }
    }
    out += c;
    i += 1;
  }
  if (inClass) throw new RegexError("unterminated character set");
  return out;
}

export function compilePattern(pattern) {
  if (typeof pattern !== "string") {
    throw new RegexError("first argument must be string or compiled pattern");
  }
  if (cache.has(pattern)) {
    const cached = cache.get(pattern);
    if (cached instanceof RegexError) throw cached;
    return cached;
  }
  let compiled;
  try {
    compiled = new RegExp(translate(pattern));
  } catch (err) {
    const wrapped =
      err instanceof RegexError ? err : new RegexError(String(err && err.message));
    cache.set(pattern, wrapped);
    throw wrapped;
  }
  cache.set(pattern, compiled);
  return compiled;
}

/** True when `pattern` matches anywhere inside `text` (Python `re.search`). */
export function search(pattern, text) {
  const re = compilePattern(pattern);
  re.lastIndex = 0;
  return re.test(text);
}

export function isValidPattern(pattern) {
  try {
    compilePattern(pattern);
    return true;
  } catch {
    return false;
  }
}

