/**
 * `jsonschema.exceptions` analogues.
 *
 * Only the parts the script observes are modelled: the `validator` keyword and
 * the instance path of each error (that is what `ErrorTree` indexes on) plus
 * the `context` list used by `anyOf`/`oneOf`.
 */

const UNSET = Symbol("unset");

export class ValidationError {
  constructor(message, opts = {}) {
    this.message = message;
    this.path = opts.path ? [...opts.path] : []; // relative_path
    this.schemaPath = opts.schemaPath ? [...opts.schemaPath] : [];
    this.context = opts.context || [];
    this.cause = opts.cause || null;
    this.validator = "validator" in opts ? opts.validator : UNSET;
    this.validatorValue = "validatorValue" in opts ? opts.validatorValue : UNSET;
    this.instance = "instance" in opts ? opts.instance : UNSET;
    this.schema = "schema" in opts ? opts.schema : UNSET;
    this.parent = null;
  }

  /** `_Error._set` - fills in only the attributes still unset. */
  _set(kwargs) {
    for (const [k, v] of Object.entries(kwargs)) {
      if (this[k] === UNSET) this[k] = v;
    }
  }

  get validatorOrNull() {
    return this.validator === UNSET ? null : this.validator;
  }
}

export class SchemaError extends Error {
  constructor(error) {
    super(error.message);
    this.name = "jsonschema.exceptions.SchemaError";
    this.error = error;
  }
}

export class Unresolvable extends Error {
  constructor(ref) {
    super(`${JSON.stringify(ref)} does not exist within the remote schema`);
    this.name = "referencing.exceptions.Unresolvable";
    this.ref = ref;
  }
}

export class UnknownType extends Error {
  constructor(type) {
    super(`Unknown type ${JSON.stringify(type)}`);
    this.name = "jsonschema.exceptions.UnknownType";
  }
}

export class FormatError extends Error {
  constructor(message, cause = null) {
    super(message);
    this.name = "jsonschema.exceptions.FormatError";
    this.cause = cause;
  }
}

/**
 * `jsonschema.exceptions.ErrorTree`.
 *
 * Errors are filed by their instance path; within one node they are stored in a
 * mapping keyed by the failing keyword, so two errors that share both a path
 * and a keyword collapse into one.
 */
export class ErrorTree {
  constructor(errors = []) {
    this.errors = new Map(); // validator keyword -> error
    this.children = new Map(); // path element -> ErrorTree

    for (const error of errors) {
      let container = this;
      for (const element of error.path) {
        const key = typeof element === "number" ? `i${element}` : `k${element}`;
        if (!container.children.has(key)) container.children.set(key, new ErrorTree());
        container = container.children.get(key);
      }
      container.errors.set(error.validatorOrNull, error);
    }
  }

  get total_errors() {
    let total = this.errors.size;
    for (const child of this.children.values()) total += child.total_errors;
    return total;
  }
}

