/**
 * The slice of `urllib.parse` that `referencing` relies on: `urlsplit`,
 * `urlunsplit`, `urljoin` and `urldefrag`, plus the key normalisation that
 * `jsonschema._utils.URIDict` performs (`urlsplit(uri).geturl()`, which quietly
 * drops an empty fragment so `".../schema#"` and `".../schema"` are one key).
 */

const SPLIT_RE =
  /^(?:([a-zA-Z][a-zA-Z0-9+.\-]*):)?(\/\/[^/?#]*)?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/;

const USES_RELATIVE = new Set([
  "",
  "ftp",
  "http",
  "gopher",
  "nntp",
  "imap",
  "wais",
  "file",
  "https",
  "shttp",
  "mms",
  "prospero",
  "rtsp",
  "rtspu",
  "sftp",
  "svn",
  "svn+ssh",
  "ws",
  "wss",
]);

const USES_NETLOC = new Set([
  "",
  "ftp",
  "http",
  "gopher",
  "nntp",
  "telnet",
  "imap",
  "wais",
  "file",
  "mms",
  "https",
  "shttp",
  "snews",
  "prospero",
  "rtsp",
  "rtspu",
  "rsync",
  "svn",
  "svn+ssh",
  "sftp",
  "nfs",
  "git",
  "git+ssh",
  "ws",
  "wss",
  "itms-services",
]);

export function urlsplit(url, defaultScheme = "") {
  const m = SPLIT_RE.exec(url);
  if (m === null) {
    return { scheme: defaultScheme, netloc: null, path: url, query: "", fragment: "" };
  }
  return {
    scheme: m[1] === undefined ? defaultScheme : m[1].toLowerCase(),
    netloc: m[2] === undefined ? null : m[2].slice(2),
    path: m[3] === undefined ? "" : m[3],
    query: m[4] === undefined ? "" : m[4],
    fragment: m[5] === undefined ? "" : m[5],
  };
}

export function urlunsplit({ scheme, netloc, path, query, fragment }) {
  let url = path;
  if (netloc !== null && netloc !== undefined) {
    if (netloc || url.startsWith("//")) {
      if (url && !url.startsWith("/")) url = "/" + url;
      url = "//" + netloc + url;
    }
  } else if (url.startsWith("//")) {
    url = "//" + url;
  }
  if (scheme) url = scheme + ":" + url;
  if (query) url = url + "?" + query;
  if (fragment) url = url + "#" + fragment;
  return url;
}

export function urldefrag(url) {
  if (url.includes("#")) {
    const parts = urlsplit(url);
    const fragment = parts.fragment;
    return [urlunsplit({ ...parts, fragment: "" }), fragment];
  }
  return [url, ""];
}

export function urljoin(base, url) {
  if (!base) return url;
  if (!url) return base;

  const b = urlsplit(base);
  const r = urlsplit(url, b.scheme);

  if (r.scheme !== b.scheme || !USES_RELATIVE.has(r.scheme)) return url;

  let netloc = r.netloc;
  if (USES_NETLOC.has(r.scheme)) {
    if (netloc) {
      return urlunsplit({ ...r, netloc });
    }
    netloc = b.netloc;
  }

  if (!r.path) {
    const query = r.query || b.query;
    return urlunsplit({ scheme: r.scheme, netloc, path: b.path, query, fragment: r.fragment });
  }

  const baseParts = b.path.split("/");
  if (baseParts[baseParts.length - 1] !== "") baseParts.pop();

  let segments;
  if (r.path.startsWith("/")) {
    segments = r.path.split("/");
  } else {
    segments = baseParts.concat(r.path.split("/"));
    const middle = segments.slice(1, -1).filter((s) => s !== "");
    segments = [segments[0], ...middle, segments[segments.length - 1]];
  }

  const resolved = [];
  for (const seg of segments) {
    if (seg === "..") {
      if (resolved.length) resolved.pop();
    } else if (seg === ".") {
      continue;
    } else {
      resolved.push(seg);
    }
  }
  const last = segments[segments.length - 1];
  if (last === "." || last === "..") resolved.push("");

  return urlunsplit({
    scheme: r.scheme,
    netloc,
    path: resolved.join("/") || "/",
    query: r.query,
    fragment: r.fragment,
  });
}

/** `URIDict.normalize` - the canonical key used for the metaschema table. */
export function normalizeUri(uri) {
  const parts = urlsplit(uri);
  return urlunsplit(parts);
}

/** JSON Pointer unescaping applied by `referencing`, after percent decoding. */
export function unquote(text) {
  try {
    return decodeURIComponent(text);
  } catch {
    return text;
  }
}

